function f(a: number): number { return a; }
async function af(): Promise<number> { return 1; }
function* g(): Generator<number> { yield 1; }
const arrow = (x: number): number => x;
const anon: (x: number) => number = (x: number): number => x;
class K { m(): number { return 1; } }
function dflt(cb: (x: number) => number = f): void { console.log(cb); }
function main(): void {
  console.log(f);
  console.log(af);
  console.log(g);
  console.log(arrow);
  console.log(anon);
  console.log([f, af]);
  console.log({ f, af, arrow });
  const o: { h: (x: number) => number } = { h(x: number): number { return x; } };
  console.log(o);
  console.log(o.h);
  console.log(new K().m);
  dflt();
  const opt: ((x: number) => number) | undefined = f;
  console.log(opt);
  console.log("x", f);
  console.log((): number => 1);
  console.log([(): number => 1]);
}
